from __future__ import annotations

import re

_ALIGNMENTS = ("left", "right", "center")
_DELIMITER = re.compile(r"^:?-+:?$")


def _cell_text(value: object) -> str:
    """The escaped text of one cell."""
    text = "" if value is None else str(value)
    return text.replace("|", "\\|")


def _pad(text: str, width: int, align: str | None) -> str:
    """Pad ``text`` to ``width`` according to ``align``."""
    extra = width - len(text)
    if align == "right":
        return " " * extra + text
    if align == "center":
        left = extra // 2
        return " " * left + text + " " * (extra - left)
    return text + " " * extra


def _delimiter_cell(width: int, align: str | None) -> str:
    """The delimiter cell for a column of ``width``."""
    if align == "left":
        return ":" + "-" * (width - 1)
    if align == "right":
        return "-" * (width - 1) + ":"
    if align == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _split_row(line: str) -> list[str]:
    """Split one table line into stripped, unescaped cells."""
    line = line.strip()
    cells: list[str] = []
    current: list[str] = []
    last_was_delimiter = False
    index = 0
    while index < len(line):
        char = line[index]
        if char == "\\" and index + 1 < len(line) and line[index + 1] == "|":
            current.append("|")
            last_was_delimiter = False
            index += 2
        elif char == "|":
            cells.append("".join(current).strip())
            current = []
            last_was_delimiter = True
            index += 1
        else:
            current.append(char)
            last_was_delimiter = False
            index += 1
    cells.append("".join(current).strip())

    if line.startswith("|"):
        cells.pop(0)
    if last_was_delimiter and cells:
        cells.pop()
    return cells


def _parse_delimiter(cell: str) -> str | None:
    """Read one delimiter cell's alignment."""
    if not _DELIMITER.match(cell):
        raise ValueError(f"invalid delimiter cell: {cell!r}")
    left = cell.startswith(":")
    right = cell.endswith(":")
    if left and right:
        return "center"
    if left:
        return "left"
    if right:
        return "right"
    return None


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    if align is None:
        align = [None] * len(header)
    else:
        if len(align) != len(header):
            raise ValueError("align needs one entry per column")
        for value in align:
            if value is not None and value not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {value!r}")

    header_cells = [_cell_text(value) for value in header]
    row_cells = []
    for row in rows:
        if len(row) > len(header):
            raise ValueError("row has more cells than the header")
        cells = [_cell_text(value) for value in row]
        cells.extend([""] * (len(header) - len(cells)))
        row_cells.append(cells)

    widths = []
    for index, cell in enumerate(header_cells):
        width = len(cell)
        for cells in row_cells:
            width = max(width, len(cells[index]))
        widths.append(max(width, 3))

    def render(cells: list[str]) -> str:
        return "| " + " | ".join(cells) + " |"

    lines = [
        render(
            [
                _pad(cell, widths[index], align[index])
                for index, cell in enumerate(header_cells)
            ]
        )
    ]
    lines.append(
        render(
            [
                _delimiter_cell(widths[index], align[index])
                for index in range(len(widths))
            ]
        )
    )
    for cells in row_cells:
        lines.append(
            render(
                [
                    _pad(cell, widths[index], align[index])
                    for index, cell in enumerate(cells)
                ]
            )
        )
    return "\n".join(lines)


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    if len(lines) < 2:
        raise ValueError("a table needs a header and a delimiter line")

    header = _split_row(lines[0])
    delimiter_cells = _split_row(lines[1])
    if len(delimiter_cells) != len(header):
        raise ValueError("delimiter line does not match the header")
    align = [_parse_delimiter(cell) for cell in delimiter_cells]

    rows = []
    for line in lines[2:]:
        cells = _split_row(line)
        if len(cells) != len(header):
            raise ValueError("row does not match the header")
        rows.append(cells)
    return header, rows, align

